export const PET_STATES = [
    'idle',
    'sleep',
    'walk',
    'thinking',
    'working',
    'needsInput',
    'complete',
    'error',
    'offline',
];
export const PET_SETTINGS_QUERY = 'xyPet';
export const DEFAULT_PET_ACCENT_COLOR = '#2c86f0';
export function stripThinkBlocks(value) {
    let visible = '';
    let depth = 0;
    let index = 0;
    while (index < value.length) {
        if (value[index] === '<') {
            const remaining = value.slice(index);
            const tag = remaining.match(/^<\s*(\/?)\s*think(?:\s[^>]*)?>/i);
            if (tag) {
                depth = tag[1] ? Math.max(0, depth - 1) : depth + 1;
                index += tag[0].length;
                continue;
            }
            const lower = remaining.toLowerCase();
            const incompleteTag = '<think>'.startsWith(lower)
                || '</think>'.startsWith(lower)
                || /^<think(?:\s[^>]*)?$/i.test(remaining)
                || /^<\/think\s*$/i.test(remaining);
            if (incompleteTag)
                break;
        }
        if (depth === 0)
            visible += value[index];
        index += 1;
    }
    return visible;
}
export function petSettingsUrl(clientUrl) {
    const url = new URL(clientUrl);
    url.searchParams.set(PET_SETTINGS_QUERY, 'settings');
    return url.toString();
}
export function consumePetSettingsUrl(clientUrl) {
    const url = new URL(clientUrl);
    const requested = url.searchParams.get(PET_SETTINGS_QUERY) === 'settings';
    if (requested)
        url.searchParams.delete(PET_SETTINGS_QUERY);
    return { requested, cleanUrl: url.toString() };
}
export const PET_ACTIVITY_KINDS = [
    'thinking',
    'tool',
    'assistant',
    'needsInput',
    'complete',
    'error',
];
const MAX_ACTIVITY_TEXT = 8_000;
export const PET_CHAT_IMAGE_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'];
export const MAX_CHAT_IMAGES = 4;
export const MAX_CHAT_IMAGE_BYTES = 8 * 1024 * 1024;
const MAX_CHAT_IMAGE_BASE64_LENGTH = Math.ceil(MAX_CHAT_IMAGE_BYTES / 3) * 4;
const MAX_STATUS_TEXT = 280;
export function boundedStatusText(value) {
    if (typeof value !== 'string')
        return undefined;
    const normalized = value.replace(/\s+/g, ' ').trim();
    if (!normalized)
        return undefined;
    return normalized.slice(0, MAX_STATUS_TEXT);
}
export function initialSnapshot(time = Date.now()) {
    return { state: 'offline', connected: false, facing: 'right', sequence: 0, time };
}
export function reducePetEvent(previous, event) {
    const time = event.time ?? Date.now();
    const base = { ...previous, sequence: previous.sequence + 1, time };
    const { text: _previousText, ...baseWithoutText } = base;
    switch (event.type) {
        case 'bridge/connected':
            return { ...baseWithoutText, connected: true, state: 'idle' };
        case 'bridge/disconnected':
            return { ...base, connected: false, state: 'offline', text: 'Harness disconnected' };
        case 'agent/running':
            return {
                ...base,
                connected: true,
                sessionId: event.sessionId,
                state: 'thinking',
                text: 'Thinking',
                ...(event.turn !== undefined ? { turn: event.turn } : {}),
            };
        case 'agent/idle':
            return { ...baseWithoutText, connected: true, sessionId: event.sessionId, state: 'idle' };
        case 'step/working':
            return {
                ...base,
                connected: true,
                sessionId: event.sessionId,
                state: 'working',
                text: boundedStatusText(event.text) ?? 'Working',
            };
        case 'assistant/text':
            const text = boundedStatusText(event.text);
            return {
                ...baseWithoutText,
                connected: true,
                sessionId: event.sessionId,
                state: previous.state === 'working' ? 'working' : 'thinking',
                ...(text ? { text } : {}),
            };
        case 'agent/needs-input':
            return {
                ...base,
                connected: true,
                sessionId: event.sessionId,
                state: 'needsInput',
                text: boundedStatusText(event.text) ?? 'Needs your input',
            };
        case 'turn/complete':
            return {
                ...base,
                connected: true,
                sessionId: event.sessionId,
                state: 'complete',
                text: boundedStatusText(event.text) ?? 'Done',
            };
        case 'agent/error':
            return {
                ...base,
                connected: true,
                sessionId: event.sessionId,
                state: 'error',
                text: boundedStatusText(event.text) ?? 'Something went wrong',
            };
    }
}
export function isBridgeClientMessage(value) {
    if (!value || typeof value !== 'object')
        return false;
    const message = value;
    if (message.type === 'auth')
        return typeof message.token === 'string' && message.token.length <= 256;
    if (message.type === 'focus')
        return true;
    if (message.type === 'shutdown-service')
        return true;
    if (message.type === 'theme-import-result') {
        return typeof message.requestId === 'string' && message.requestId.length <= 128 &&
            typeof message.ok === 'boolean' &&
            (message.ok ? typeof message.themeId === 'string' && message.themeId.length <= 64 : typeof message.error === 'string' && message.error.length <= 500);
    }
    if (message.type === 'acknowledge')
        return typeof message.sessionId === 'string' && message.sessionId.length <= 256;
    if (message.type === 'approval-decision') {
        return typeof message.requestId === 'string' && message.requestId.length <= 128 &&
            typeof message.sessionId === 'string' && message.sessionId.length <= 256 &&
            (message.outcome === 'allowed-once' || message.outcome === 'rejected');
    }
    if (message.type === 'question-answer') {
        return typeof message.requestId === 'string' && message.requestId.length <= 128 &&
            typeof message.sessionId === 'string' && message.sessionId.length <= 256 &&
            validQuestionAnswers(message.answers);
    }
    if (message.type === 'open-client') {
        return message.sessionId === undefined || (typeof message.sessionId === 'string' && message.sessionId.length <= 256);
    }
    if (message.type === 'treasure-found')
        return true;
    if (message.type !== 'chat' || typeof message.requestId !== 'string' || message.requestId.length > 128 ||
        typeof message.text !== 'string' || message.text.length > 8_000 ||
        (message.sessionId !== undefined && (typeof message.sessionId !== 'string' || message.sessionId.length > 256)))
        return false;
    const images = message.images;
    if (images !== undefined && (!Array.isArray(images) || images.length > MAX_CHAT_IMAGES || !images.every(validChatImage)))
        return false;
    if (images && images.reduce((total, image) => total + image.data.length, 0) > MAX_CHAT_IMAGE_BASE64_LENGTH)
        return false;
    return message.text.trim().length > 0 || Boolean(images?.length);
}
function validChatImage(value) {
    if (!value || typeof value !== 'object')
        return false;
    const image = value;
    return typeof image.name === 'string' && image.name.length > 0 && image.name.length <= 255 &&
        PET_CHAT_IMAGE_TYPES.includes(image.mediaType) &&
        typeof image.data === 'string' && image.data.length > 0 && image.data.length <= MAX_CHAT_IMAGE_BASE64_LENGTH;
}
export function isBridgeServerMessage(value) {
    if (!value || typeof value !== 'object')
        return false;
    const message = value;
    if (message.type === 'snapshot') {
        const snapshot = message.snapshot;
        const sessions = snapshot?.sessions;
        const validSessions = sessions === undefined ||
            (Array.isArray(sessions) &&
                sessions.length <= 64 &&
                sessions.every((entry) => {
                    if (!entry || typeof entry !== 'object')
                        return false;
                    const session = entry;
                    return (typeof session.id === 'string' &&
                        session.id.length <= 256 &&
                        typeof session.title === 'string' &&
                        session.title.length <= 120 &&
                        PET_STATES.includes(session.state) &&
                        typeof session.unread === 'boolean' &&
                        typeof session.updatedAt === 'number' &&
                        (session.text === undefined || (typeof session.text === 'string' && session.text.length <= 600)) &&
                        (session.turn === undefined || (Number.isInteger(session.turn) && session.turn >= 0)) &&
                        (session.activities === undefined || (Array.isArray(session.activities) &&
                            session.activities.length <= 16 &&
                            session.activities.every((entry) => {
                                if (!entry || typeof entry !== 'object')
                                    return false;
                                const activity = entry;
                                return typeof activity.id === 'string' && activity.id.length <= 128 &&
                                    PET_ACTIVITY_KINDS.includes(activity.kind) &&
                                    typeof activity.text === 'string' && activity.text.length > 0 && activity.text.length <= MAX_ACTIVITY_TEXT &&
                                    typeof activity.time === 'number';
                            }))) &&
                        (session.approval === undefined || (typeof session.approval === 'object' && session.approval !== null &&
                            typeof session.approval.requestId === 'string' &&
                            session.approval.requestId.length <= 128 &&
                            typeof session.approval.toolName === 'string' &&
                            session.approval.toolName.length <= 80)) &&
                        (session.question === undefined || validQuestionRequest(session.question)));
                }));
        return Boolean(snapshot &&
            PET_STATES.includes(snapshot.state) &&
            typeof snapshot.connected === 'boolean' &&
            (snapshot.facing === 'left' || snapshot.facing === 'right') &&
            typeof snapshot.sequence === 'number' &&
            typeof snapshot.time === 'number' &&
            (snapshot.turn === undefined || (Number.isInteger(snapshot.turn) && snapshot.turn >= 0)) &&
            validSessions);
    }
    if (message.type === 'theme-import') {
        return typeof message.requestId === 'string' && message.requestId.length <= 128 &&
            typeof message.path === 'string' && message.path.length <= 1024;
    }
    if (message.type === 'quit')
        return true;
    return ((message.type === 'chat-result' || message.type === 'approval-result' || message.type === 'question-result') &&
        typeof message.requestId === 'string' &&
        typeof message.ok === 'boolean' &&
        (message.ok || typeof message.error === 'string'));
}
function validQuestionRequest(value) {
    if (!value || typeof value !== 'object')
        return false;
    const request = value;
    if (typeof request.requestId !== 'string' || request.requestId.length === 0 || request.requestId.length > 128)
        return false;
    if (!Array.isArray(request.questions) || request.questions.length === 0 || request.questions.length > 8)
        return false;
    return request.questions.every((entry) => {
        if (!entry || typeof entry !== 'object')
            return false;
        const question = entry;
        return typeof question.id === 'string' && question.id.length > 0 && question.id.length <= 128 &&
            typeof question.question === 'string' && question.question.length > 0 && question.question.length <= 600 &&
            (question.header === undefined || (typeof question.header === 'string' && question.header.length <= 80)) &&
            (question.detail === undefined || (typeof question.detail === 'string' && question.detail.length <= 4_000)) &&
            (question.multiSelect === undefined || typeof question.multiSelect === 'boolean') &&
            (question.options === undefined || (Array.isArray(question.options) && question.options.length <= 12 && question.options.every((entry) => {
                if (!entry || typeof entry !== 'object')
                    return false;
                const option = entry;
                return typeof option.label === 'string' && option.label.length > 0 && option.label.length <= 120 &&
                    (option.description === undefined || (typeof option.description === 'string' && option.description.length <= 500));
            })));
    });
}
function validQuestionAnswers(value) {
    return Array.isArray(value) && value.length > 0 && value.length <= 8 && value.every((entry) => {
        if (!entry || typeof entry !== 'object')
            return false;
        const answer = entry;
        return typeof answer.id === 'string' && answer.id.length > 0 && answer.id.length <= 128 &&
            Array.isArray(answer.selected) && answer.selected.length <= 12 &&
            answer.selected.every((label) => typeof label === 'string' && label.length > 0 && label.length <= 120) &&
            (answer.custom === undefined || (typeof answer.custom === 'string' && answer.custom.trim().length > 0 && answer.custom.length <= 2_000));
    });
}
